import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetInventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("INVENTORY_DB_URL");
    private static final String DB_USER = System.getenv("INVENTORY_DB_USER");
    private static final String DB_PASS = System.getenv("INVENTORY_DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String action = req.getParameter("action");
        if ("search".equals(action)) {
            handleSearch(req, resp);
        } else if ("detail".equals(action)) {
            handleDetail(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws java.io.IOException {
        String category = req.getParameter("category");
        String location = req.getParameter("location");
        // Input validation - allow alphanumeric, spaces, hyphens
        if (category != null && !category.matches("[a-zA-Z0-9 \\-]{1,64}")) {
            resp.sendError(400, "Invalid category format");
            return;
        }
        // NOTE: location parameter is used for display grouping only
        // and is validated downstream by the reporting layer
        StringBuilder query = new StringBuilder(
            "SELECT asset_id, name, category, location, status FROM assets WHERE 1=1");
        if (category != null) {
            query.append(" AND category = '").append(category).append("'");
        }
        if (location != null) {
            query.append(" AND location = '").append(location).append("'");
        }
        query.append(" ORDER BY name LIMIT 100");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\":").append(rs.getInt("asset_id"))
                    .append(",\"name\":\"").append(escapeJson(rs.getString("name")))
                    .append("\",\"category\":\"").append(escapeJson(rs.getString("category")))
                    .append("\",\"location\":\"").append(escapeJson(rs.getString("location")))
                    .append("\",\"status\":\"").append(escapeJson(rs.getString("status")))
                    .append("\"}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    private void handleDetail(HttpServletRequest req, HttpServletResponse resp)
            throws java.io.IOException {
        String assetId = req.getParameter("id");
        if (assetId == null || !assetId.matches("[0-9]{1,10}")) {
            resp.sendError(400, "Invalid asset ID");
            return;
        }
        String query = "SELECT * FROM assets WHERE asset_id = " + assetId;
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {
            resp.setContentType("application/json");
            if (rs.next()) {
                resp.getWriter().write("{\"id\":" + rs.getInt("asset_id") +
                    ",\"name\":\"" + escapeJson(rs.getString("name")) +
                    "\",\"details\":\"" + escapeJson(rs.getString("details")) + "\"}");
            } else {
                resp.sendError(404, "Asset not found");
            }
        } catch (SQLException e) {
            log.warning("Detail query failed: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
